{"provenance":"deterministic","nodes":[{"name":"decideLifecycleActions","kind":"function","path":"processor/supersession/lifecycle.go","lines":[182,251],"body":"func decideLifecycleActions(inScope []gtypes.EntityState, reason string, stat func(path string) bool) (toMark []message.Triple, toClear []string, pathCount int) {
	if stat == nil {
		// Nothing to check liveness against — the source itself is gone, so
		// every in-scope entity is unconditionally stale.
		for i := range inScope {
			if isMarkedStale(inScope[i].Triples) {
				continue
			}
			toMark = append(toMark, staleTriple(inScope[i].ID, reason))
		}
		return toMark, toClear, 0
	}

	parentCounts := make(map[string]int)
	for _, entity := range inScope {
		if n, ok := tripleInt(entity.Triples, source.DocChunkCount); ok && n >= 0 {
			parentCounts[entity.ID] = n
		}
	}
	byPath := make(map[string][]gtypes.EntityState)
	for i := range inScope {
		p, ok := pathOf(inScope[i].Triples)
		if !ok {
			continue // no path predicate — can't determine liveness
		}
		byPath[p] = append(byPath[p], inScope[i])
	}
	pathCount = len(byPath)

	for path, group := range byPath {
		present := stat(path)
		if !present {
			for i := range group {
				if !isMarkedStale(group[i].Triples) {
					toMark = append(toMark, staleTriple(group[i].ID, reason))
				}
			}
			continue
		}
		// The file is present, but a document that SHRANK leaves passages
		// behind that no filesystem check can see: every passage of a
		// ten-passage document that is now seven passages long still carries
		// the path of a file that is very much still there. The parent's
		// DocChunkCount is the only evidence, so liveness for a passage is
		// index < count rather than stat().
		for i := range group {
			if isSourceRemoved(group[i].Triples) {
				continue
			}
			liveCount, haveCount := passageParentCount(group[i], parentCounts)
			marked := isMarkedStale(group[i].Triples)
			vanished := haveCount && isVanishedPassage(group[i].Triples, liveCount)
			switch {
			case vanished && !marked:
				toMark = append(toMark, staleTriple(group[i].ID, graph.LifecycleReasonPassageRemoved))
			case !vanished && marked:
				// Without the parent's count there is no evidence either way, so
				// clearing a passage's marker here would resurrect a genuinely
				// vanished passage whenever enumeration truncated before its
				// parent — and re-mark it on the next full pass. Absence of
				// evidence must not read as evidence of liveness.
				if !haveCount && isPassage(group[i].Triples) {
					continue
				}
				toClear = append(toClear, group[i].ID)
			}
		}
	}
	return toMark, toClear, pathCount
}","relations":{"callee":[{"name":"isMarkedStale","path":"processor/supersession/lifecycle.go","line":335},{"name":"isPassage","path":"processor/supersession/lifecycle.go","line":285},{"name":"isSourceRemoved","path":"processor/supersession/lifecycle.go","line":274},{"name":"isVanishedPassage","path":"processor/supersession/lifecycle.go","line":294},{"name":"passageParentCount","path":"processor/supersession/lifecycle.go","line":255},{"name":"pathOf","path":"processor/supersession/lifecycle.go","line":346},{"name":"staleTriple","path":"processor/supersession/lifecycle.go","line":357},{"name":"tripleInt","path":"processor/supersession/lifecycle.go","line":303}],"caller":[{"name":"TestAbsentSet_LeavesPresentObjectsAlone","path":"processor/supersession/lifecycle_absent_test.go","line":119},{"name":"TestAbsentSet_MarksParentAndPassagesTogether","path":"processor/supersession/lifecycle_absent_test.go","line":86},{"name":"TestAbsentSet_ReappearedArtifactIsCleared","path":"processor/supersession/lifecycle_absent_test.go","line":160},{"name":"TestDecideLifecycleActions_AllPassagesLive_NoAction","path":"processor/supersession/lifecycle_passage_test.go","line":272},{"name":"TestDecideLifecycleActions_CodeEntitiesUnaffectedByPassageRules","path":"processor/supersession/lifecycle_passage_test.go","line":394},{"name":"TestDecideLifecycleActions_DeletedFile_MarksParentAndEveryPassage","path":"processor/supersession/lifecycle_passage_test.go","line":310},{"name":"TestDecideLifecycleActions_NumericTriplesSurviveJSONRoundTrip","path":"processor/supersession/lifecycle_passage_test.go","line":430},{"name":"TestDecideLifecycleActions_PassagesWithoutParent_NeverMarked","path":"processor/supersession/lifecycle_passage_test.go","line":333},{"name":"TestDecideLifecycleActions_PreChunkingDocument_BehavesAsBefore","path":"processor/supersession/lifecycle_passage_test.go","line":358},{"name":"TestDecideLifecycleActions_RegrownDocument_ClearsRevivedPassages","path":"processor/supersession/life